package com.tunemind.app.domain.recommendation

enum class RecommendationCategory {
    /** High-affinity favorites that the user returns to with high receptivity. */
    FAMILIAR_RECEPTIVE,

    /** Fresh discoveries derived from demonstrated artist anchors and acoustic preferences. */
    EXPLORATION_DISCOVERY,

    /** Tracks that completed cooldown in the vault and are acoustically restored. */
    COOLDOWN_RESTORED,

    /** Low-fatigue contrasting tracks to reset sensory saturation. */
    PALATE_CLEANSER
}

/**
 * A track recommendation generated by TuneMind's Personal Music Intelligence Agent.
 * Grounded in observable playback evidence with a transparent reason.
 */
data class RecommendedTrack(
    val id: String,
    val title: String,
    val artist: String,
    val album: String? = null,
    val genre: String? = null,
    val reason: String,
    val confidence: Float, // 0.0 to 1.0
    val category: RecommendationCategory,
    val suggestedProviderId: String? = "spotify",
    val providerTrackId: String? = null,
    val observationCountBasis: Int = 1
)
